"""Database session helpers."""

from dataclasses import dataclass


@dataclass
class QueryResult:
    rows: list[dict]


class DatabaseSession:
    """Tiny fake database session used by the fixture."""

    def execute(self, query: str, params: dict | None = None) -> QueryResult:
        return QueryResult(rows=[])

    def fetch_one(self, query: str, params: dict | None = None) -> dict | None:
        return None

    def close(self) -> None:
        return None


def create_session() -> DatabaseSession:
    """Create a new database session."""
    return DatabaseSession()


def session_scope() -> DatabaseSession:
    """Return a scoped session object."""
    return create_session()

"""Time helpers."""

from datetime import datetime, timezone


def utc_now() -> datetime:
    return datetime.now(timezone.utc)

from src.billing import invoices


class TimeoutSession:
    def execute(self, query: str, params: dict | None = None) -> None:
        raise TimeoutError("write timed out")

    def rollback(self) -> None:
        pass


def test_retry_timeout_is_a_recoverable_result(monkeypatch) -> None:
    monkeypatch.setattr(invoices, "create_session", TimeoutSession)

    assert invoices.InvoiceRepository().mark_retry_requested("inv-1") is False

